// Get the transcript
const transcript = $('init_variables').first().json.transcript;

// Split the transcript into lines
const lines = transcript.split('\n');

// Add an additional newline between each user and AI chat
const formatted_transcript = lines.map((line, index) => {
  if (index > 0 && (line.startsWith('AI:') || line.startsWith('User:'))) {
    return '\n' + line;
  } else {
    return line;
  }
}).join('\n');

// Return the formatted transcript
return { formatted_transcript };

const transcript = $('init_variables').first().json.transcript

// Count the words in one turn. An empty segment counts as zero words:
// "".split(/\s+/) returns [""], so without this guard a bare "AI:" line would be
// counted as one word spoken.
function countWords(segment) {
    const text = segment.trim();
    return text.length === 0 ? 0 : text.split(/\s+/).length;
}

let bot_word_count = 0;
let user_word_count = 0;

// The transcript is one line per turn, prefixed "AI:" or "User:".
for (const line of transcript.split('\n')) {
    const turn = line.trim();
    if (turn.startsWith('AI:')) {
        bot_word_count += countWords(turn.slice(3));
    } else if (turn.startsWith('User:')) {
        user_word_count += countWords(turn.slice(5));
    }
}

const total_word_count = bot_word_count + user_word_count;

// Talk share as NUMBERS from 0 to 100, not strings with a '%' suffix.
//
// This used to return "83%" — a decorated string handed to a numeric Airtable
// column, which left the type coercion to the destination. Airtable happens to
// parse "83%" back into the value a Percent field stores, which is why most rows
// read correctly; but a value that survives only by coercion is one field-type
// change away from being wrong, and this column is already wrong in the earliest
// five rows. Emit a real number and let the
// field do the formatting.
//
// The caller's share is the complement of the agent's, so the pair always sums
// to 100 instead of rounding independently to 99 or 101.
//
// A call with no words at all has no talk share, so it reports null rather than
// a misleading 0.
let bot_word_percent = null;
let user_word_percent = null;
if (total_word_count > 0) {
    bot_word_percent = Math.round((bot_word_count / total_word_count) * 1000) / 10;
    user_word_percent = Math.round((100 - bot_word_percent) * 10) / 10;
}

return {
    bot_word_count: bot_word_count,
    user_word_count: user_word_count,
    total_word_count: total_word_count,
    bot_word_percent: bot_word_percent,
    user_word_percent: user_word_percent
};

