function sanitizeJSON(jsonString) {
    // Replace problematic quotes and newlines within the JSON string
    return jsonString
        .replace(/"([^"]*?)"/g, (match, group) => {
            // Ensure keys and properly quoted values remain intact
            if (/:$/.test(match) || /^[\s\[{"]/.test(match)) {
                return match; // Leave valid JSON quotes untouched
            }
            // Escape any other problematic quotes
            return `"${group.replace(/"/g, '\\"')}"`;
        })
        //.replace(/\n/g, " "); // Replace \n with a space or any desired character
}

return {
  output:sanitizeJSON($json.output.replace(/\n/g, " ").replace(/\"/g, ' \\"'))
}
